end

function PTTQ_Go(p, talk)
	if not PTTQ_SrcOk() then Say(PTTQ_T_BLOCKED, 1, PTTQ_T_CLOSE .. "/PTTQ_No") return end
	local sw = SubWorldID2Idx(p.map)
	if not sw or sw < 0 then Msg2Player(p.nm .. PTTQ_T_NOMAP) return end
	if NewWorld(p.map, p.x, p.y) == 0 then Msg2Player(PTTQ_T_NOGO .. p.nm .. ".") return end
	if p.map == 1021 then SetFightState(0) else SetFightState(1) end
	local s = PTTQ_T_ARRIVE .. p.nm .. " [" .. floor(p.nx / 8) .. "," .. floor(p.ny / 16) .. "]."
	if talk then s = s .. PTTQ_T_TALK end
	Msg2Player(s)
end

