function PTTQ_List(p)
	PTTQ_Load()
	local first = (p - 1) * 4 + 1
	local last = first + 3
	local more = 1
	if PTTQ_N - first + 1 <= 5 then last = PTTQ_N more = nil end
	local cur = PTTQ_Cur()
	local o = {}
	local n = 0
	local i = first
	while i <= last do
		local pt = PTTQ_PT[i]
		local mk = "[ ] "
		if i == cur then mk = "[>] " end
		n = n + 1
		o[n] = mk .. pt.nm .. " [" .. floor(pt.nx / 8) .. "," .. floor(pt.ny / 16) .. "]/PTTQ_G" .. i
		i = i + 1
	end
	if more then n = n + 1 o[n] = PTTQ_T_MORE .. "/PTTQ_L" .. (p + 1) end
	if p > 1 then n = n + 1 o[n] = PTTQ_T_BACK .. "/PTTQ_L" .. (p - 1) else n = n + 1 o[n] = PTTQ_T_BACK .. "/main" end
	n = n + 1 o[n] = PTTQ_T_CLOSE .. "/PTTQ_No"
	PTTQ_Say(PTTQ_T_LTITLE, o)
end

